-- Упражнения книги 19, глава 29 (Администрирование Linux). Файл строит автор-скрипт (не в репозитории); после правок можно редактировать и вручную.

INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 29, 'la29-grep-parse', 0, 'func', 'Разбор вывода git grep -n', 'Напишите функцию grep_matches(output): output - текст, который напечатал git grep -n (возможно, с -W или -p, а также с --heading и --break). Верните список [путь, номер_строки, текст] только для СТРОК-СОВПАДЕНИЙ, в порядке вывода. Формат строк: без --heading каждая строка начинается с пути и разделителя, потом номер строки, тот же разделитель и текст. Разделитель '':'' у строки с совпадением, ''-'' у строки контекста (-W, -A, -B, -C), ''='' у строки с именем функции (-p, -W). Путь заканчивается на первом месте, где подряд идут разделитель, число и тот же разделитель. С --heading имя файла печатается один раз отдельной строкой, а дальше идут строки вида ''число:текст'' (совпадение), ''число-текст'' (контекст), ''число=текст'' (функция). Строка ''--'' разделяет группы, пустая строка (--break) разделяет файлы, строка ''Binary file ПУТЬ matches'' игнорируется. Текст совпадения может сам содержать двоеточия и числа. Номер строки возвращайте числом. Пути в тестах не содержат фрагментов вида '':число:'', ''-число-'', ''=число=''.', 'def grep_matches(output):
    return []
', 'Для строки без заголовка подойдёт регулярное выражение с нежадным путём и обратной ссылкой на разделитель: ^(.+?)([:=-])(\d+)\2(.*)$. Если файл задан заголовком, строку разбирайте как ^(\d+)([:=-])(.*)$.', '{"func": "grep_matches", "tests": [{"args": ["accel/kvm/kvm-accel-ops.c:31:static void *kvm_vcpu_thread_fn(void *arg)\naccel/kvm/kvm-accel-ops.c:74:    qemu_thread_create(cpu->thread, thread_name, kvm_vcpu_thread_fn,\naccel/kvm/kvm-all.c:3464:        run_ret = kvm_vcpu_ioctl(cpu, KVM_RUN, 0);"], "expected": [["accel/kvm/kvm-accel-ops.c", 31, "static void *kvm_vcpu_thread_fn(void *arg)"], ["accel/kvm/kvm-accel-ops.c", 74, "    qemu_thread_create(cpu->thread, thread_name, kvm_vcpu_thread_fn,"], ["accel/kvm/kvm-all.c", 3464, "        run_ret = kvm_vcpu_ioctl(cpu, KVM_RUN, 0);"]]}, {"args": ["accel/kvm/kvm-accel-ops.c=68=static void kvm_start_vcpu_thread(CPUState *cpu)\naccel/kvm/kvm-accel-ops.c-71-\naccel/kvm/kvm-accel-ops.c:72:    snprintf(thread_name, VCPU_THREAD_NAME_SIZE, \"CPU %d/KVM\",\naccel/kvm/kvm-accel-ops.c-73-             cpu->cpu_index);\n--\naccel/tcg/tcg-accel-ops-mttcg.c=121=static void mttcg_start_vcpu_thread(CPUState *cpu)\naccel/tcg/tcg-accel-ops-mttcg.c:133:    snprintf(thread_name, VCPU_THREAD_NAME_SIZE, \"CPU %d/TCG\",\naccel/tcg/tcg-accel-ops-mttcg.c-134-             cpu->cpu_index);"], "expected": [["accel/kvm/kvm-accel-ops.c", 72, "    snprintf(thread_name, VCPU_THREAD_NAME_SIZE, \"CPU %d/KVM\","], ["accel/tcg/tcg-accel-ops-mttcg.c", 133, "    snprintf(thread_name, VCPU_THREAD_NAME_SIZE, \"CPU %d/TCG\","]]}, {"args": ["accel/kvm/kvm-all.c\n3463-        trace_kvm_run_exit(cpu->cpu_index, run->exit_reason);\n3464:        switch (run->exit_reason) {\n3465-        case KVM_EXIT_IO:\n3519:        case KVM_EXIT_MMIO: /* a:12:b */\n\nhw/block/virtio-blk.c\n100-    /* 7:8: not a header */\n101:    aio_bh_schedule_oneshot(ctx, fn, s); /* a-1-b */\nBinary file docs/logo.png matches\n102:    done:3:"], "expected": [["accel/kvm/kvm-all.c", 3464, "        switch (run->exit_reason) {"], ["accel/kvm/kvm-all.c", 3519, "        case KVM_EXIT_MMIO: /* a:12:b */"], ["hw/block/virtio-blk.c", 101, "    aio_bh_schedule_oneshot(ctx, fn, s); /* a-1-b */"], ["hw/block/virtio-blk.c", 102, "    done:3:"]]}, {"args": ["hw/block/virtio-blk.c-100-    /* see util/async.c:57: for the BH */\nhw/block/virtio-blk.c:101:    aio_bh_schedule_oneshot(ctx, fn, s); /* a-1-b */\n--\nhw/virtio/virtio.c-2000-    x = 1;\nhw/virtio/virtio.c:2001:    y = 2; /* :3: */\nBinary file docs/logo.png matches"], "expected": [["hw/block/virtio-blk.c", 101, "    aio_bh_schedule_oneshot(ctx, fn, s); /* a-1-b */"], ["hw/virtio/virtio.c", 2001, "    y = 2; /* :3: */"]]}, {"args": [""], "expected": []}, {"args": ["accel/kvm/kvm-all.c-3463-x\n--\naccel/kvm/kvm-all.c=3400=int kvm_cpu_exec(CPUState *cpu)\n"], "expected": []}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 29, 'la29-tags-lookup', 1, 'func', 'Поиск в файле tags', 'Напишите функцию find_tag(tags, name, from_file, kind): tags - текст файла tags в формате ctags (universal-ctags), name - точное имя, from_file - имя файла, из которого ищут, или None, kind - буква вида или None. Каждая строка: имя, файл и остальное, всё через табуляцию. Остальное - адрес, потом '';"'', потом поля через табуляцию. Строки, начинающиеся с ''!'', - служебные, пропускайте их. Адрес - либо число (номер строки), либо шаблон /^...$/ (в шаблоне ''\/'' означает ''/'', ''\\'' означает ''\''). Адрес заканчивается на ПОСЛЕДНЕМ вхождении '';"'' в строке: сам шаблон может содержать такие символы. Поля: поле без двоеточия - вид (kind); ''kind:X'' - тоже вид; ''file:'' (пустое значение) - статический символ, видимый только в своём файле; ''line:N'' - номер строки; ''struct:X'', ''class:X'', ''union:X'', ''enum:X'', ''function:X'' - область (scope); остальные поля игнорируйте. Верните список строк [файл, номер_строки, вид, область, шаблон]: номер берётся из поля line, а если его нет - из числового адреса, иначе None; область и шаблон - None, если их нет; в шаблоне нет рамки ''/^'' и ''$/''. Берите только теги с точно таким именем; если kind задан - только этого вида; статические теги - только если from_file равен их файлу или from_file равен None. Порядок: по файлу, затем по номеру строки (None считайте нулём).', 'def find_tag(tags, name, from_file, kind):
    return []
', 'rest.rfind('';"'') отделяет адрес от полей. Строку разбирайте так: name, file, rest = line.split(''\t'', 2); поля - rest[idx+2:].split(''\t'') без пустых.', '{"func": "find_tag", "tests": [{"args": ["!_TAG_FILE_FORMAT\t2\t/extended format; --format=1 will not append ;\" to lines/\n!_TAG_FILE_SORTED\t1\t/0=unsorted, 1=sorted, 2=foldcase/\n!_TAG_PROGRAM_NAME\tUniversal Ctags\t/Derived from Exuberant Ctags/\nJob\tsrc/job.c\t/^struct Job {$/;\"\ts\tline:3\nJob\tsrc/job.h\t/^typedef struct Job Job;$/;\"\tkind:t\tline:9\ncpu_index\tinclude/hw/core/cpu.h\t/^    int cpu_index;$/;\"\tm\tstruct:CPUState\tline:442\nfmt\tsrc/util.c\t/^static const char *fmt = \";\";$/;\"\tv\tfile:\tline:5\nhelper\tsrc/a.c\t/^static int helper(void)$/;\"\tf\tfile:\tline:10\nhelper\tsrc/b.c\t/^static int helper(void)$/;\"\tf\tfile:\tline:77\nkvm_cpu_exec\taccel/kvm/kvm-all.c\t/^int kvm_cpu_exec(CPUState *cpu)$/;\"\tf\ttyperef:typename:int\tline:3427\nkvm_cpu_exec\taccel/kvm/kvm-cpus.h\t/^int kvm_cpu_exec(CPUState *cpu);$/;\"\tp\ttyperef:typename:int\tline:15\nkvm_vcpu_thread_fn\taccel/kvm/kvm-accel-ops.c\t31;\"\tf\tfile:\nkvm_vcpu_thread_fn\taccel/kvm/kvm-accel-ops.h\t/^void *kvm_vcpu_thread_fn(void *arg);$/;\"\tkind:p\tline:4\npath\tsrc/dev.c\t/^static char *path = \"\\/dev\\/kvm\";$/;\"\tv\tfile:\tline:8\n", "kvm_cpu_exec", null, null], "expected": [["accel/kvm/kvm-all.c", 3427, "f", null, "int kvm_cpu_exec(CPUState *cpu)"], ["accel/kvm/kvm-cpus.h", 15, "p", null, "int kvm_cpu_exec(CPUState *cpu);"]]}, {"args": ["!_TAG_FILE_FORMAT\t2\t/extended format; --format=1 will not append ;\" to lines/\n!_TAG_FILE_SORTED\t1\t/0=unsorted, 1=sorted, 2=foldcase/\n!_TAG_PROGRAM_NAME\tUniversal Ctags\t/Derived from Exuberant Ctags/\nJob\tsrc/job.c\t/^struct Job {$/;\"\ts\tline:3\nJob\tsrc/job.h\t/^typedef struct Job Job;$/;\"\tkind:t\tline:9\ncpu_index\tinclude/hw/core/cpu.h\t/^    int cpu_index;$/;\"\tm\tstruct:CPUState\tline:442\nfmt\tsrc/util.c\t/^static const char *fmt = \";\";$/;\"\tv\tfile:\tline:5\