/;\"\tv\tfile:\tline:5\nhelper\tsrc/a.c\t/^static int helper(void)$/;\"\tf\tfile:\tline:10\nhelper\tsrc/b.c\t/^static int helper(void)$/;\"\tf\tfile:\tline:77\nkvm_cpu_exec\taccel/kvm/kvm-all.c\t/^int kvm_cpu_exec(CPUState *cpu)$/;\"\tf\ttyperef:typename:int\tline:3427\nkvm_cpu_exec\taccel/kvm/kvm-cpus.h\t/^int kvm_cpu_exec(CPUState *cpu);$/;\"\tp\ttyperef:typename:int\tline:15\nkvm_vcpu_thread_fn\taccel/kvm/kvm-accel-ops.c\t31;\"\tf\tfile:\nkvm_vcpu_thread_fn\taccel/kvm/kvm-accel-ops.h\t/^void *kvm_vcpu_thread_fn(void *arg);$/;\"\tkind:p\tline:4\npath\tsrc/dev.c\t/^static char *path = \"\\/dev\\/kvm\";$/;\"\tv\tfile:\tline:8\n", "helper", "src/b.c", null], "expected": [["src/b.c", 77, "f", null, "static int helper(void)"]]}, {"args": ["!_TAG_FILE_FORMAT\t2\t/extended format; --format=1 will not append ;\" to lines/\n!_TAG_FILE_SORTED\t1\t/0=unsorted, 1=sorted, 2=foldcase/\n!_TAG_PROGRAM_NAME\tUniversal Ctags\t/Derived from Exuberant Ctags/\nJob\tsrc/job.c\t/^struct Job {$/;\"\ts\tline:3\nJob\tsrc/job.h\t/^typedef struct Job Job;$/;\"\tkind:t\tline:9\ncpu_index\tinclude/hw/core/cpu.h\t/^    int cpu_index;$/;\"\tm\tstruct:CPUState\tline:442\nfmt\tsrc/util.c\t/^static const char *fmt = \";\";$/;\"\tv\tfile:\tline:5\nhelper\tsrc/a.c\t/^static int helper(void)$/;\"\tf\tfile:\tline:10\nhelper\tsrc/b.c\t/^static int helper(void)$/;\"\tf\tfile:\tline:77\nkvm_cpu_exec\taccel/kvm/kvm-all.c\t/^int kvm_cpu_exec(CPUState *cpu)$/;\"\tf\ttyperef:typename:int\tline:3427\nkvm_cpu_exec\taccel/kvm/kvm-cpus.h\t/^int kvm_cpu_exec(CPUState *cpu);$/;\"\tp\ttyperef:typename:int\tline:15\nkvm_vcpu_thread_fn\taccel/kvm/kvm-accel-ops.c\t31;\"\tf\tfile:\nkvm_vcpu_thread_fn\taccel/kvm/kvm-accel-ops.h\t/^void *kvm_vcpu_thread_fn(void *arg);$/;\"\tkind:p\tline:4\npath\tsrc/dev.c\t/^static char *path = \"\\/dev\\/kvm\";$/;\"\tv\tfile:\tline:8\n", "kvm", null, null], "expected": []}, {"args": ["!_TAG_FILE_FORMAT\t2\t/extended format; --format=1 will not append ;\" to lines/\n!_TAG_FILE_SORTED\t1\t