INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 29, 'la29-blame-porcelain', 2, 'func', 'Разбор git blame --porcelain', 'Напишите функцию parse_blame(text): text - вывод git blame --porcelain для одного файла. Формат: перед каждой группой строк из одного коммита идёт заголовок ''<40 hex> <исходная строка> <строка в файле> <число строк в группе>''. У следующих строк той же группы заголовок короче: ''<40 hex> <исходная строка> <строка в файле>''. Сведения о коммите (author, author-mail, author-time, summary, filename и другие) печатаются ТОЛЬКО при первой встрече коммита, а у следующих групп того же коммита их нет. Сама строка файла идёт после заголовка и начинается с табуляции (табуляцию уберите). Незнакомые строки заголовка (например, previous и boundary) игнорируйте. Верните словарь {''lines'': [[номер_строки_в_файле, первые_8_символов_хеша, автор, текст], ...] в порядке файла, ''authors'': [[автор, число_строк], ...]}; авторов сортируйте по убыванию числа строк, при равенстве - по имени.', 'def parse_blame(text):
    return {''lines'': [], ''authors'': []}
', 'Сначала проверяйте строку на ведущую табуляцию: это содержимое файла, и в нём может быть что угодно. Запоминайте автора по хешу при первой встрече и подставляйте для следующих групп.', '{"func": "parse_blame", "tests": [{"args": ["aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa 1 1 2\nauthor Ann Example\nauthor-mail <ann@example.org>\nauthor-time 1700000000\nauthor-tz +0000\ncommitter Ann Example\ncommitter-mail <ann@example.org>\ncommitter-time 1700000000\ncommitter-tz +0000\nsummary kvm: add the run loop\nfilename accel/kvm/kvm-all.c\n\tint kvm_cpu_exec(CPUState *cpu)\naaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa 2 2\n\t{\nbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb 3 3 1\nauthor Bob Sample\nauthor-mail <bob@example.org>\nauthor-time 1700000000\nauthor-tz +0000\ncommitter Bob Sample\ncommitter-mail <bob@example.org>\ncommitter-time 1700000000\ncommitter-tz +0000\nsummary kvm: drop the BQL around KVM_RUN\nprevious aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa accel/kvm/kvm-all.c\nfilename accel/kvm/kvm-all.c\n\t    bql_unlock();\naaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa 4 4 2\n\t    do {\naaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa 5 5\n\t        run_ret = kvm_vcpu_ioctl(cpu, KVM_RUN, 0);\n"], "expected": {"lines": [[1, "aaaaaaaa", "Ann Example", "int kvm_cpu_exec(CPUState *cpu)"], [2, "aaaaaaaa", "Ann Example", "{"], [3, "bbbbbbbb", "Bob Sample", "    bql_unlock();"], [4, "aaaaaaaa", "Ann Example", "    do {"], [5, "aaaaaaaa", "Ann Example", "        run_ret = kvm_vcpu_ioctl(cpu, KVM_RUN, 0);"]], "authors": [["Ann Example", 4], ["Bob Sample", 1]]}}, {"args": ["cccccccccccccccccccccccccccccccccccccccc 1 1 2\nauthor Cy Tester\nauthor-mail <cy@example.org>\nauthor-time 1700000000\nauthor-tz +0000\ncommitter Cy Tester\ncommitter-mail <cy@example.org>\ncommitter-time 1700000000\ncommitter-tz +0000\nsummary initial import\nboundary\nfilename accel/kvm/kvm-all.c\n\ta\ncccccccccccccccccccccccccccccccccccccccc 2 2\n\tb\ndddddddddddddddddddddddddddddddddddddddd 1 3 1\nauthor Ann Example\nauthor-mail <ann@example.org>\nauthor-time 1700000000\nauthor-tz +0000\ncommitter Ann Example\ncommitter-mail <ann@example.org>\ncommitter-time 1700000000\ncommitter-tz +0000\nsummary fix spelling\nfilename accel/kvm/kvm-all.c\n\tc\neeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeee 2 4 1\nauthor Bob Sample\nauthor-mail <bob@example.org>\nauthor-time 1700000000\nauthor-tz +0000\ncommitter Bob Sample\ncommitter-mail <bob@example.org>\ncommitter-time 1700000000\ncommitter-tz +0000\nsummary rename a to b\nfilename accel/kvm/kvm-all.c\n\td\nffffffffffffffffffffffffffffffffffffffff 3 5 1\nauthor Ann Example\nauthor-mail <ann@example.org>\nauthor-time 1700000000\nauthor-tz +0000\ncommitter Ann Example\ncommitter-mail <ann@example.org>\ncommitter-time 1700000000\ncommitter-tz +0000\nsummary add e\nfilename accel/kvm/kvm-all.c\n\te\ncccccccccccccccccccccccccccccccccccccccc 3 6 1\n\tf\n"], "expected": {"lines": [[1, "cccccccc", "Cy Tester", "a"], [2, "cccccccc", "Cy Tester", "b"], [3, "dddddddd", "Ann Example", "c"], [4, "eeeeeeee", "Bob Sample", "d"], [5, "ffffffff", "Ann Example", "e"], [6, "cccccccc", "Cy Tester", "f"]], "authors": [["Cy Tester", 3], ["Ann Example", 2], ["Bob Sample", 1]]}}, {"args": [""], "expected": {"lines": [], "authors": []}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 29, 'la29-gdb-threads', 3, 'func', 'Потоки и стеки из gdb', 'Напишите функцию summarize_threads(text): text - вывод gdb -batch -ex ''thread apply all bt'' для процесса. gdb печатает потоки по убыванию номера. Заголовок потока: ''Thread N (ОПИСАНИЕ):'', где ОПИСАНИЕ содержит ''(LWP число)'' или ''process число'', а в конце, возможно, имя потока в двойных кавычках: ''Thread 2 (Thread 0x7f.. (LWP 4249) "CPU 0/KVM"):''. Строка кадра: ''#N  '' + (адрес ''0x... in '' - не всегда) + функция + '' ('' + аргументы + '')'' + ('' at файл:строка'' или '' from библиотека'' - не всегда). Аргументы могут содержать вложенные скобки и строки в кавычках, внутри которых встречается даже '' at x.c:9''. Функция может называться ''??''. Строки, которые не начинаются с ''#'' и не являются заголовком потока (локальные переменные, ''(More stack frames follow...)'', предупреждения, ''[New LWP ...]''), игнорируйте. Верните список по ВОЗРАСТАНИЮ номера потока, по строке на поток: [номер, LWP, имя_или_None, функция_кадра_0, число_кадров, ''файл:строка'' первого сверху кадра, у которого есть '' at файл:строка'', или None]. LWP - число (для ''process N'' берите N).', 'def summarize_threads(text):
    return []
', 'Разбор кадра: уберите ''#N  '' и необязательное ''0x... in '', возьмите имя до первого '' ('', затем пройдите по символам, считая скобки и пропуская кавычки, чтобы найти закрывающую скобку аргументов; хвост после неё - '' at ...'' или '' from ...''.', '{"func": "summarize_threads", "tests": [{"args": ["[New LWP 4249]\nwarning: Loadable section \".note.gnu.property\" outside of ELF segments\n\nThread 3 (Thread 0x7f1c2b2ff6c0 (LWP 4251) \"IO mon_iothread\"):\n#0  0x00007f1c2e0ab1ef in ppoll () from /lib64/libc.so.6\n#1  0x000055d4e1f4d2c4 in qemu_poll_ns (fds=0x7f1c2b2fe0d0, nfds=2, timeout=-1) at ../util/qemu-timer.c:342\n#2  0x000055d4e1f5a7aa in qemu_thread_start (args=0x55d4e3a0c9f0) at ../util/qemu-thread-posix.c:393\n#3  0x00007f1c2e09f9eb in start_thread () from /lib64/libc.so.6\n\nThread 2 (Thread 0x7f1c2c0016c0 (LWP 4249) \"CPU 0/KVM\"):\n#0  0x00007f1c2e0a0b1d in ioctl () from /lib64/libc.so.6\n#1  0x000055d4e1c3b9ae in kvm_vcpu_ioctl (cpu=0x55d4e3a31d60, type=44672) at ../accel/kvm/kvm-all.c:3085\n#2  0x000055d4e1c3bd11 in kvm_cpu_exec (cpu=0x55d4e3a31d60) at ../accel/kvm/kvm-all.c:3464\n#3  0x000055d4e1c3f604 in kvm_vcpu_thread_fn (arg=0x55d4e3a31d60) at ../accel/kvm/kvm-accel-ops.c:54\n#4  0x000055d4e1f5a7aa in qemu_thread_start (args=<optimized out>) at ../util/qemu-thread-posix.c:393\n#5  0x00007f1c2e09f9eb in ?? ()\n#6  0x0000000000000000 in ?? ()\n\nThread 1 (Thread 0x7f1c2e0e4a40 (LWP 4242) \"qemu-system-x86\"):\n#0  0x00007f1c2e0ab1ef in ppoll () from /lib64/libc.so.6\n#1  0x000055d4e1f4d2c4 in os_host_main_loop_wait (name=0x55d4e2a1 \"a (b) at x.c:9\", timeout=4) at ../util/main-loop.c:464\n        timeout_ns = 4000000\n#2  main (argc=2, argv=0x7ffd8f3c2a28) at ../system/main.c:95\n(More stack frames follow...)"], "expected": [[1, 4242, "qemu-system-x86", "ppoll", 3, "../util/main-loop.c:464"], [2, 4249, "CPU 0/KVM", "ioctl", 7, "../accel/kvm/kvm-all.c:3085"], [3, 4251, "IO mon_iothread", "ppoll", 4, "../util/qemu-timer.c:342"]]}, {"args": ["Thread 2 (Thread 0x7f0000000700 (LWP 9002)):\n#0  0x00007f00 in ?? ()\n\nThread 1 (process 9001):\n#0  main () at t.c:3\n#1  0x00007f01 in __libc_start_main () from /lib/libc.so.6"], "expected": [[1, 9001, null, "main", 2, "t.c:3"], [2, 9002, null, "??", 1, null]]}, {"args": [""], "expected": []}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 29, 'la29-perf-fold', 4, 'func', 'От perf script к свёрнутым стекам', 'Напишите функцию fold_perf_script(text), которая превращает вывод perf script (по образцу stackcollapse-perf.pl) в свёрнутые стеки для flame graph. Образцы разделены пустой строкой; строки, начинающиеся с ''#'', пропускайте. Заголовок образца - строка, начинающаяся не с пробела: ''comm pid/tid [cpu] время: период событие:'' (период может отсутствовать, тогда он равен 1; pid/tid бывает и просто ''tid''). Имя comm может содержать пробелы, например ''CPU 0/KVM''. Событие - последнее слово перед двоеточием в конце строки. Учитывайте только образцы того события, которое встретилось ПЕРВЫМ, остальные пропускайте. Далее идут строки кадров, САМЫЙ ГЛУБОКИЙ кадр первым: ''адрес символ (модуль)''. Из символа уберите суффикс ''+0x...''; символ ''[unknown]'' замените на ''[имя_файла_модуля]'' (последний компонент пути модуля), а если модуль тоже ''[unknown]'' - на ''[unknown]''; '';'' в символе замените на '':''. Результат: список строк ''comm;корень;...;лист период'', где comm с пробелами заменён на ''_'' и стоит первым, кадры идут от корня к листу, а периоды одинаковых стеков сложены. Отсортируйте строки как обычные строки.', 'def fold_perf_script(text):
    return []
', 'Заголовок: re.match(r''^(\S.*?)\s+(\d+)/*(\d+)*\s+'', line), период и событие: re.search(r'':\s*(\d+)*\s+(\S+):\s*$'', line). Кадр: re.match(r''^\s*(\w+)\s*(.+) \((.*)\)'', line). Кадры читаются от листа, поэтому вставляйте каждый новый в начало списка.', '{"func": "fold_perf_script", "tests": [{"args": ["# ========\n# captured on    : Tue Nov  3 18:00:00 2026\n# ========\n#\nCPU 0/KVM 4242/4249 [003] 7000.100001: 250000 cycles:\n\tffffffffc0f1a2b3 vmx_vcpu_run+0x1b3 ([kvm_intel])\n\tffffffffc0e90c11 kvm_arch_vcpu_ioctl_run+0x6c1 ([kvm])\n\t00007f1c2e0a0b1d ioctl+0xd (/usr/lib64/libc.so.6)\n\t000055d4e1c3bd11 kvm_cpu_exec+0x1b1 (/usr/bin/qemu-system-x86_64)\n\t000055d4e1c3f604 kvm_vcpu_thread_fn+0x84 (/usr/bin/qemu-system-x86_64)\n\t00007f1c2e09f9eb start_thread+0x2ab (/usr/lib64/libc.so.6)\n\nCPU 0/KVM 4242/4249 [003] 7000.101001: 250000 cycles:\n\tffffffffc0f1a2b3 vmx_vcpu_run+0x1b3 ([kvm_intel])\n\tffffffffc0e90c11 kvm_arch_vcpu_ioctl_run+0x6c1 ([kvm])\n\t00007f1c2e0a0b1d ioctl+0xd (/usr/lib64/libc.so.6)\n\t000055d4e1c3bd11 kvm_cpu_exec+0x1b1 (/usr/bin/qemu-system-x86_64)\n\t000055d4e1c3f604 kvm_vcpu_thread_fn+0x84 (/usr/bin/qemu-system-x86_64)\n\t00007f1c2e09f9eb start_thread+0x2ab (/usr/lib64/libc.so.6)\n\nCPU 0/KVM 4242/4249 [003] 7000.102001: 125000 cycles:\n\t000055d4e1c3bd90 kvm_cpu_exec+0x230 (/usr/bin/qemu-system-x86_64)\n\t000055d4e1c3f604 kvm_vcpu_thread_fn+0x84 (/usr/bin/qemu-system-x86_64)\n\t00007f1c2e09f9eb start_thread+0x2ab (/usr/lib64/libc.so.6)\n\nqemu-system-x86 4242/4242 [001] 7000.103001: 90000 cycles:\n\t00007f1c2e0ab1ef ppoll+0x4f (/usr/lib64/libc.so.6)\n\t00007f1c2f000000 [unknown] (/usr/lib64/libglib-2.0.so.0.7800.0)\n\t00007ffd1234abcd [unknown] ([unknown])\n\t000055d4e1f4d2c4 qemu_poll_ns+0x24 (/usr/bin/qemu-system-x86_64)\n\nCPU 0/KVM 4242/4249 [003] 7000.104001: 1 instructions:\n\t000055d4e1c3bd90 kvm_cpu_exec+0x230 (/usr/bin/qemu-system-x86_64)\n"], "expected": ["CPU_0/KVM;start_thread;kvm_vcpu_thread_fn;kvm_cpu_exec 125000", "CPU_0/KVM;start_thread;kvm_vcpu_thread_fn;kvm_cpu_exec;ioctl;kvm_arch_vcpu_ioctl_run;vmx_vcpu_run 500000", "qemu-system-x86;qemu_poll_ns;[unknown];[libglib-2.0.so.0.7800.0];ppoll 90000"]}, {"args": ["worker 10 [000] 1.0: cpu-clock:\n\t7f00 b;x+0x4 (/bin/prog)\n\t7f01 a (/bin/prog)\n\nworker 10 [000] 2.0: cpu-clock:\n\t7f00 b;x+0x4 (/bin/prog)\n\t7f01 a (/bin/prog)\n"], "expected": ["worker;a;b:x 2"]}, {"args": [""], "expected": []}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 29, 'la29-perf-profile', 5, 'func', 'Self и Children по свёрнутым стекам', 'Напишите функцию profile(lines): lines - список свёрнутых стеков ''корень;...;лист число'', как их печатает stackcollapse-perf.pl. Число - вес образцов, имена кадров не содержат пробелов. Пустые строки пропускайте. Для каждой функции посчитайте self - вес стеков, где она ЛИСТ, и children (в perf report это колонка Children, то есть включительное время) - вес стеков, где она встречается ХОТЯ БЫ РАЗ (рекурсия считается один раз на стек). Верните список строк [функция, self, inclusive], отсортированный по inclusive по убыванию, затем по self по убыванию, затем по имени.', 'def profile(lines):
    return []
', 'rsplit('' '', 1) отделяет вес. Для включительного времени пройдите по set(frames) каждого стека.', '{"func": "profile", "tests": [{"args": [["main;bar;foo 60", "main;bar 40"]], "expected": [["bar", 40, 100], ["main", 0, 100], ["foo", 60, 60]]}, {"args": [["start_thread;kvm_vcpu_thread_fn;kvm_cpu_exec;kvm_vcpu_ioctl 700", "start_thread;kvm_vcpu_thread_fn;kvm_cpu_exec;kvm_handle_io 100", "start_thread;kvm_vcpu_thread_fn;kvm_cpu_exec 50", "start_thread;kvm_vcpu_thread_fn;qemu_process_cpu_events 25", "start_thread;kvm_vcpu_thread_fn;kvm_cpu_exec;kvm_handle_io 25", ""]], "expected": [["kvm_vcpu_thread_fn", 0, 900], ["start_thread", 0, 900], ["kvm_cpu_exec", 50, 875], ["kvm_vcpu_ioctl", 700, 700], ["kvm_handle_io", 125, 125], ["qemu_process_cpu_events", 25, 25]]}, {"args": [["a;b;a;b;c 10", "a;b;a 5", "b 3"]], "expected": [["b", 3, 18], ["a", 5, 15], ["c", 10, 10]]}, {"args": [[]], "expected": []}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 29, 'la29-thread-classify', 6, 'func', 'Роли потоков процесса QEMU', 'Напишите функцию classify_threads(ps_output, pid): ps_output - вывод ''ps -T -o tid,comm -p PID'' (первая строка - заголовок; в каждой следующей сначала идёт идентификатор потока, потом название потока comm, в котором могут быть пробелы), pid - идентификатор процесса. Названия потоков QEMU, которые проверены по исходникам QEMU 11.1: ''CPU <n>/KVM'' и ''CPU <n>/TCG'' - поток виртуального процессора n; ''IO <id>'' - поток iothread с этим идентификатором (в том числе ''IO mon_iothread'' монитора); ''worker'' - рабочий поток пула; ''call_rcu'' - поток отложенного освобождения; ''vhost-<число>'' - поток vhost ядра. Главный поток - тот, у которого идентификатор равен pid, его имя не важно (оно совпадает с именем программы, обрезанным до 15 символов). Остальные имена - ''прочие''. Верните словарь: {''main'': tid_главного_или_None, ''vcpus'': [[номер, tid], ...] по возрастанию номера, ''iothreads'': [[id, tid], ...] по возрастанию id как строки, ''workers'': число потоков worker, ''rcu'': tid_или_None, ''vhost'': [tid, ...] по возрастанию, ''other'': [[tid, comm], ...] по возрастанию tid}. Все tid - числа.', 'def classify_threads(ps_output, pid):
    return {}
', 'Строку делите так: tid, _, comm = line.strip().partition('' ''); comm.strip(). Сначала проверьте tid == pid, потом регулярные выражения: ^CPU (\d+)/(KVM|TCG)$, ^IO (.+)$, ^vhost-\d+$.', '{"func": "classify_threads", "tests": [{"args": ["    TID COMMAND\n   4242 qemu-system-x86\n   4249 CPU 0/KVM\n   4250 CPU 1/KVM\n   4251 IO mon_iothread\n   4252 call_rcu\n   4260 worker\n   4261 worker\n   4270 IO iothread0\n   4271 vhost-4242\n   4272 gmain\n   4273 CPU 10/KVM", 4242], "expected": {"main": 4242, "vcpus": [[0, 4249], [1, 4250], [10, 4273]], "iothreads": [["iothread0", 4270], ["mon_iothread", 4251]], "workers": 2, "rcu": 4252, "vhost": [4271], "other": [[4272, "gmain"]]}}, {"args": ["  SPID COMMAND\n   100 qemu-system-aar\n   101 CPU 0/TCG\n   102 CPU 1/TCG\n   103 qemu-system-aar\n   104 gmain", 100], "expected": {"main": 100, "vcpus": [[0, 101], [1, 102]], "iothreads": [], "workers": 0, "rcu": null, "vhost": [], "other": [[103, "qemu-system-aar"], [104, "gmain"]]}}, {"args": ["  SPID COMMAND\n   100 qemu-system-aar\n   101 CPU 0/TCG\n   102 CPU 1/TCG\n   103 qemu-system-aar\n   104 gmain", 999], "expected": {"main": null, "vcpus": [[0, 101], [1, 102]], "iothreads": [], "workers": 0, "rcu": null, "vhost": [], "other": [[100, "qemu-system-aar"], [103, "qemu-system-aar"], [104, "gmain"]]}}, {"args": ["TID COMMAND\n", 1], "expected": {"main": null, "vcpus": [], "iothreads": [], "workers": 0, "rcu": null, "vhost": [], "other": []}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 29, 'la29-call-path', 7, 'func', 'Кратчайший путь от точки входа к функции', 'Напишите функцию find_path(graph, entries, goal): graph - словарь ''функция -> список вызываемых ею функций'' (то, что вы собираете по git grep и gdb bt), entries - список возможных точек входа (например, имена из стека потока), goal - целевая функция. Верните КРАТЧАЙШИЙ путь [точка_входа, ..., goal] по рёбрам графа. Если кратчайших путей несколько, верните лексикографически наименьший (списки имён сравниваются по элементам). Если goal равна точке входа, путь состоит из неё одной. Если пути нет, верните []. Функции, которых нет среди ключей графа, считаются вызывающими никого. В графе есть циклы. Точек входа в entries может не быть в графе - тогда они просто не ведут никуда (но могут быть целью).', 'def find_path(graph, entries, goal):
    return []
', 'Обратный поиск в ширину от goal даёт расстояния dist до цели. Потом идите вперёд: выберите вход с минимальным dist (при равенстве - меньшее имя), на каждом шаге берите наименьшего преемника с dist на единицу меньше.', '{"func": "find_path", "tests": [{"args": [{"qemu_thread_start": ["kvm_vcpu_thread_fn", "iothread_run", "worker_thread"], "kvm_vcpu_thread_fn": ["rcu_register_thread", "bql_lock", "kvm_init_vcpu", "qemu_process_cpu_events", "kvm_cpu_exec"], "kvm_cpu_exec": ["kvm_vcpu_ioctl", "kvm_handle_io", "address_space_rw", "qemu_system_reset_request", "bql_unlock", "bql_lock"], "kvm_handle_io": ["address_space_rw"], "address_space_rw": ["memory_region_dispatch_write"], "memory_region_dispatch_write": ["memory_region_write_accessor", "bql_lock"], "iothread_run": ["aio_poll"], "aio_poll": ["aio_dispatch", "aio_bh_poll"], "aio_dispatch": ["aio_bh_poll"], "aio_bh_poll": ["virtio_blk_dma_restart_bh"], "worker_thread": [], "loop_a": ["loop_b"], "loop_b": ["loop_a", "target"]}, ["qemu_thread_start"], "address_space_rw"], "expected": ["qemu_thread_start", "kvm_vcpu_thread_fn", "kvm_cpu_exec", "address_space_rw"]}, {"args": [{"qemu_thread_start": ["kvm_vcpu_thread_fn", "iothread_run", "worker_thread"], "kvm_vcpu_thread_fn": ["rcu_register_thread", "bql_lock", "kvm_init_vcpu", "qemu_process_cpu_events", "kvm_cpu_exec"], "kvm_cpu_exec": ["kvm_vcpu_ioctl", "kvm_handle_io", "address_space_rw", "qemu_system_reset_request", "bql_unlock", "bql_lock"], "kvm_handle_io": ["address_space_rw"], "address_space_rw": ["memory_region_dispatch_write"], "memory_region_dispatch_write": ["memory_region_write_accessor", "bql_lock"], "iothread_run": ["aio_poll"], "aio_poll": ["aio_dispatch", "aio_bh_poll"], "aio_dispatch": ["aio_bh_poll"], "aio_bh_poll": ["virtio_blk_dma_restart_bh"], "worker_thread": [], "loop_a": ["loop_b"], "loop_b": ["loop_a", "target"]}, ["qemu_thread_start"], "memory_region_write_accessor"], "expected": ["qemu_thread_start", "kvm_vcpu_thread_fn", "kvm_cpu_exec", "address_space_rw", "memory_region_dispatch_write", "memory_region_write_accessor"]}, {"args": [{"qemu_thread_start": ["kvm_vcpu_thread_fn", "iothread_run", "worker_thread"], "kvm_vcpu_thread_fn": ["rcu_register_thread", "bql_lock", "kvm_init_vcpu", "qemu_process_cpu_events", "kvm_cpu_exec"], "kvm_cpu_exec": ["kvm_vcpu_ioctl", "kvm_handle_io", "address_space_rw", "qemu_system_reset_request", "bql_unlock", "bql_lock"], "kvm_handle_io": ["address_space_rw"], "address_space_rw": ["memory_region_dispatch_write"], "memory_region_dispatch_write": ["memory_region_write_accessor", "bql_lock"], "iothread_run": ["aio_poll"], "aio_poll": ["aio_dispatch", "aio_bh_poll"], "aio_dispatch": ["aio_bh_poll"], "aio_bh_poll": ["virtio_blk_dma_restart_bh"], "worker_thread": [], "loop_a": ["loop_b"], "loop_b": ["loop_a", "target"]}, ["qemu_thread_start"], "aio_bh_poll"], "expected": ["qemu_thread_start", "iothread_run", "aio_poll", "aio_bh_poll"]}, {"args": [{"qemu_thread_start": ["kvm_vcpu_thread_fn", "iothread_run", "worker_thread"], "kvm_vcpu_thread_fn": ["rcu_register_thread", "bql_lock", "kvm_init_vcpu", "qemu_process_cpu_events", "kvm_cpu_exec"], "kvm_cpu_exec": ["kvm_vcpu_ioctl", "kvm_handle_io", "address_space_rw", "qemu_system_reset_request", "bql_unlock", "bql_lock"], "kvm_handle_io": ["address_space_rw"], "address_space_rw": ["memory_region_dispatch_write"], "memory_region_dispatch_write": ["memory_region_write_accessor", "bql_lock"], "iothread_run": ["aio_poll"], "aio_poll": ["aio_dispatch", "aio_bh_poll"], "aio_dispatch": ["aio_bh_poll"], "aio_bh_poll": ["virtio_blk_dma_restart_bh"], "worker_thread": [], "loop_a": ["loop_b"], "loop_b": ["loop_a", "target"]}, ["worker_thread", "iothread_run"], "virtio_blk_dma_restart_bh"], "expected": ["iothread_run", "aio_poll", "aio_bh_poll", "virtio_blk_dma_restart_bh"]}, {"args": [{"qemu_thread_start": ["kvm_vcpu_thread_fn", "iothread_run", "worker_thread"], "kvm_vcpu_thread_fn": ["rcu_register_thread", "bql_lock", "kvm_init_vcpu", "qemu_process_cpu_events", "kvm_cpu_exec"], "kvm_cpu_exec": ["kvm_vcpu_ioctl", "kvm_handle_io", "address_space_rw", "qemu_system_reset_request", "bql_unlock", "bql_lock"], "kvm_handle_io": ["address_space_rw"], "address_space_rw": ["memory_region_dispatch_write"], "memory_region_dispatch_write": ["memory_region_write_accessor", "bql_lock"], "iothread_run": ["aio_poll"], "aio_poll": ["aio_dispatch", "aio_bh_poll"], "aio_dispatch": ["aio_bh_poll"], "aio_bh_poll": ["virtio_blk_dma_restart_bh"], "worker_thread": [], "loop_a": ["loop_b"], "loop_b": ["loop_a", "target"]}, ["kvm_cpu_exec"], "bql_lock"], "expected": ["kvm_cpu_exec", "bql_lock"]}, {"args": [{"qemu_thread_start": ["kvm_vcpu_thread_fn", "iothread_run", "worker_thread"], "kvm_vcpu_thread_fn": ["rcu_register_thread", "bql_lock", "kvm_init_vcpu", "qemu_process_cpu_events", "kvm_cpu_exec"], "kvm_cpu_exec": ["kvm_vcpu_ioctl", "kvm_handle_io", "address_space_rw", "qemu_system_reset_request", "bql_unlock", "bql_lock"], "kvm_handle_io": ["address_space_rw"], "address_space_rw": ["memory_region_dispatch_write"], "memory_region_dispatch_write": ["memory_region_write_accessor", "bql_lock"], "iothread_run": ["aio_poll"], "aio_poll": ["aio_dispatch", "aio_bh_poll"], "aio_dispatch": ["aio_bh_poll"], "aio_bh_poll": ["virtio_blk_dma_restart_bh"], "worker_thread": [], "loop_a": ["loop_b"], "loop_b": ["loop_a", "target"]}, ["worker_thread"], "bql_lock"], "expected": []}, {"args": [{"qemu_thread_start": ["kvm_vcpu_thread_fn", "iothread_run", "worker_thread"], "kvm_vcpu_thread_fn": ["rcu_register_thread", "bql_lock", "kvm_init_vcpu", "qemu_process_cpu_events", "kvm_cpu_exec"], "kvm_cpu_exec": ["kvm_vcpu_ioctl", "kvm_handle_io", "address_space_rw", "qemu_system_reset_request", "bql_unlock", "bql_lock"], "kvm_handle_io": ["address_space_rw"], "address_space_rw": ["memory_region_dispatch_write"], "memory_region_dispatch_write": ["memory_region_write_accessor", "bql_lock"], "iothread_run": ["aio_poll"], "aio_poll": ["aio_dispatch", "aio_bh_poll"], "aio_dispatch": ["aio_bh_poll"], "aio_bh_poll": ["virtio_blk_dma_restart_bh"], "worker_thread": [], "loop_a": ["loop_b"], "loop_b": ["loop_a", "target"]}, ["loop_a"], "target"], "expected": ["loop_a", "loop_b", "target"]}, {"args": [{"qemu_thread_start": ["kvm_vcpu_thread_fn", "iothread_run", "worker_thread"], "kvm_vcpu_thread_fn": ["rcu_register_thread", "bql_lock", "kvm_init_vcpu", "qemu_process_cpu_events", "kvm_cpu_exec"], "kvm_cpu_exec": ["kvm_vcpu_ioctl", "kvm_handle_io", "address_space_rw", "qemu_system_reset_request", "bql_unlock", "bql_lock"], "kvm_handle_io": ["address_space_rw"], "address_space_rw": ["memory_region_dispatch_write"], "memory_region_dispatch_write": ["memory_region_write_accessor", "bql_lock"], "iothread_run": ["aio_poll"], "aio_poll": ["aio_dispatch", "aio_bh_poll"], "aio_dispatch": ["aio_bh_poll"], "aio_bh_poll": ["virtio_blk_dma_restart_bh"], "worker_thread": [], "loop_a": ["loop_b"], "loop_b": ["loop_a", "target"]}, ["kvm_cpu_exec"], "kvm_cpu_exec"], "expected": ["kvm_cpu_exec"]}, {"args": [{"qemu_thread_start": ["kvm_vcpu_thread_fn", "iothread_run", "worker_thread"], "kvm_vcpu_thread_fn": ["rcu_register_thread", "bql_lock", "kvm_init_vcpu", "qemu_process_cpu_events", "kvm_cpu_exec"], "kvm_cpu_exec": ["kvm_vcpu_ioctl", "kvm_handle_io", "address_space_rw", "qemu_system_reset_request", "bql_unlock", "bql_lock"], "kvm_handle_io": ["address_space_rw"], "address_space_rw": ["memory_region_dispatch_write"], "memory_region_dispatch_write": ["memory_region_write_accessor", "bql_lock"], "iothread_run": ["aio_poll"], "aio_poll": ["aio_dispatch", "aio_bh_poll"], "aio_dispatch": ["aio_bh_poll"], "aio_bh_poll": ["virtio_blk_dma_restart_bh"], "worker_thread": [], "loop_a": ["loop_b"], "loop_b": ["loop_a", "target"]}, ["nowhere"], "nowhere"], "expected": ["nowhere"]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 29, 'la29-queue-container-of', 8, 'c', 'Очередь QTAILQ и container_of своими руками', 'Это упражнение на чтение исходников: в QEMU 11.1 файл include/qemu/queue.h описывает очередь QTAILQ, а include/qemu/compiler.h - макрос container_of. Откройте их в проекте и перепишите нужные макросы как обычные функции для одного типа. Дано: struct Job с полем entry - объединением указателя tqe_next и связи QTailQLink tqe_circ; union JobQ - голова очереди. Связь tql_prev элемента указывает на связь ПРЕДЫДУЩЕГО элемента (у первого - на связь головы), связь головы указывает на связь последнего элемента, а tql_next хранит указатель на сам элемент. Напишите: макрос container_of(ptr, type, member) (по указателю на поле вернуть указатель на структуру; член может быть вложенным, например entry.tqe_circ); jobq_init, jobq_insert_tail, jobq_remove по образцу QTAILQ_INIT, QTAILQ_INSERT_TAIL и QTAILQ_REMOVE; jobq_last - последний элемент через container_of от q->tqh_circ.tql_prev; jobq_prev - как QTAILQ_PREV (у первого элемента результат NULL). Удалённый элемент должен получить tql_prev и tqe_next равными NULL (так QTAILQ_IN_USE узнаёт, что элемент не в очереди). Макрос должен использоваться в программе не менее двух раз.', '#include <stddef.h>
#include <stdint.h>

/* the layout of include/qemu/queue.h, QEMU 11.1 */
typedef struct QTailQLink {
    void *tql_next;
    struct QTailQLink *tql_prev;
} QTailQLink;

struct Job {
    int id;
    union {
        struct Job *tqe_next;
        QTailQLink tqe_circ;
    } entry;
};

union JobQ {
    struct Job *tqh_first;
    QTailQLink tqh_circ;
};

/* container_of(ptr, type, member): по указателю на поле member структуры type вернуть указатель на саму структуру.
   Как в include/qemu/compiler.h: с проверкой типа через typeof и offsetof. */
#define container_of(ptr, type, member) (0)

/* пустая очередь (как QTAILQ_INIT) */
void jobq_init(union JobQ *q) {
}

/* вставка в конец (как QTAILQ_INSERT_TAIL) */
void jobq_insert_tail(union JobQ *q, struct Job *j) {
}

/* удаление (как QTAILQ_REMOVE); у удалённого элемента tqe_circ.tql_prev и tqe_next становятся NULL */
void jobq_remove(union JobQ *q, struct Job *j) {
}

/* последний элемент или NULL: возьмите q->tqh_circ.tql_prev (указатель на поле entry.tqe_circ последнего) и вернитесь к структуре через container_of */
struct Job *jobq_last(union JobQ *q) {
    return NULL;
}

/* предыдущий элемент или NULL у первого (как QTAILQ_PREV: j->entry.tqe_circ.tql_prev->tql_prev->tql_next) */
struct Job *jobq_prev(struct Job *j) {
    return NULL;
}
', 'Для пустой очереди tqh_circ.tql_prev указывает на саму голову. При вставке в конец: связь нового элемента получает прежнее значение tqh_circ.tql_prev, затем tql_next этой связи (у пустой очереди - tqh_first) становится новым элементом, затем tqh_circ.tql_prev указывает на связь нового. Удаление - зеркальная операция.', '{"driver": "/*__DRIVER__*/\n#include <stdio.h>\n#include <string.h>\n\nstatic int src_count(const char *pat) {\n    FILE *f = fopen(\"/sandbox/main.c\", \"r\");\n    static char buf[1 << 17];\n    size_t n = fread(buf, 1, sizeof buf - 1, f);\n    buf[n] = 0;\n    fclose(f);\n    char *mk = strstr(buf, \"/*__\" \"DRIVER__*/\");\n    if (mk) *mk = 0;\n    int c = 0;\n    for (char *p = buf; (p = strstr(p, pat)) != NULL; p += strlen(pat)) c++;\n    return c;\n}\n\nstruct Box {\n    char tag[3];\n    double d;\n    struct Job job;\n};\n\nstatic void show(union JobQ *q) {\n    printf(\"fwd:\");\n    for (struct Job *j = q->tqh_first; j; j = j->entry.tqe_next)\n        printf(\" %d\", j->id);\n    printf(\" | back:\");\n    for (struct Job *j = jobq_last(q); j; j = jobq_prev(j))\n        printf(\" %d\", j->id);\n    printf(\"\\n\");\n}\n\nint main(void) {\n    struct Box b;\n    printf(\"%d\\n\", container_of(&b.job, struct Box, job) == &b);\n    printf(\"%d\\n\", container_of(&b.job.entry.tqe_circ, struct Job, entry.tqe_circ) == &b.job);\n    printf(\"%d\\n\", src_count(\"container_of(\") >= 2);\n\n    union JobQ q;\n    struct Job j[7];\n    for (int i = 0; i < 7; i++) j[i].id = i;\n    jobq_init(&q);\n    printf(\"empty: %d %d\\n\", q.tqh_first == NULL, jobq_last(&q) == NULL);\n    for (int i = 1; i <= 4; i++) jobq_insert_tail(&q, &j[i]);\n    show(&q);\n    printf(\"prev of first: %d\\n\", jobq_prev(&j[1]) == NULL);\n    jobq_remove(&q, &j[2]);\n    show(&q);\n    printf(\"detached: %d %d\\n\", j[2].entry.tqe_circ.tql_prev == NULL, j[2].entry.tqe_next == NULL);\n    jobq_remove(&q, &j[4]);\n    show(&q);\n    jobq_remove(&q, &j[1]);\n    show(&q);\n    jobq_remove(&q, &j[3]);\n    printf(\"empty again: %d %d %d\\n\", q.tqh_first == NULL, jobq_last(&q) == NULL, q.tqh_circ.tql_prev == &q.tqh_circ);\n    jobq_insert_tail(&q, &j[5]);\n    jobq_insert_tail(&q, &j[6]);\n    jobq_insert_tail(&q, &j[2]);\n    show(&q);\n    return 0;\n}\n", "expected": ["1", "1", "1", "empty: 1 1", "fwd: 1 2 3 4 | back: 4 3 2 1", "prev of first: 1", "fwd: 1 3 4 | back: 4 3 1", "detached: 1 1", "fwd: 1 3 | back: 3 1", "fwd: 3 | back: 3", "empty again: 1 1 1", "fwd: 5 6 2 | back: 2 6 5"], "flags": "-std=gnu11 -O1 -Wall"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 29, 'la29-thread-names', 9, 'c', 'Имена потоков как в QEMU: CPU n/KVM', 'Из этой главы вы знаете, что QEMU называет потоки: ''CPU %d/KVM'' для виртуального процессора (accel/kvm/kvm-accel-ops.c) и ''IO <id>'' для iothread, а qemu_thread_create ставит имя функцией pthread_setname_np (util/qemu-thread-posix.c; ошибку QEMU игнорирует, потому что имя нужно только для отладки). Это настоящий вызов ядру, и модели нет: напишите три функции. thread_set_name(name) - назвать вызывающий поток через pthread_setname_np(pthread_self(), name) и вернуть 0 или номер ошибки (по man7.org длина имени ограничена 16 байтами вместе с нулевым, длиннее - ERANGE). vcpu_thread_name(buf, size, index) - записать ''CPU <index>/KVM'' и вернуть 0, только если строка целиком влезла в буфер и не длиннее 15 символов; иначе вернуть -1 и сделать buf пустой строкой. other_thread_names(names, max) - то, что делает ''ps -T'': пройти каталог /proc/self/task, для каждого числового имени каталога, кроме идентификатора главного потока (getpid()), прочитать /proc/self/task/<tid>/comm и вернуть число имён (без перевода строки).', '#define _GNU_SOURCE
#include <dirent.h>
#include <errno.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <unistd.h>

/* Назвать вызывающий поток, как это делает qemu_thread_set_name в QEMU (pthread_setname_np).
   Вернуть 0 или номер ошибки, который вернула pthread_setname_np (ERANGE, если имя длиннее 15 символов). */
int thread_set_name(const char *name) {
    return -1;
}

/* Записать в buf (size байт) имя "CPU <index>/KVM". Вернуть 0, если имя целиком влезло и по длине не больше 15 символов
   (предел ядра), иначе -1 и пустую строку в buf. */
int vcpu_thread_name(char *buf, size_t size, int index) {
    return -1;
}

/* Имена всех потоков процесса, кроме главного (tid == getpid()): для каждого номера из каталога /proc/self/task
   прочитайте первую строку файла /proc/self/task/<tid>/comm без перевода строки. Порядок любой. Не больше max имён.
   Вернуть число имён, при ошибке -1. */
int other_thread_names(char names[][16], int max) {
    return -1;
}
', 'pthread_setname_np возвращает номер ошибки, а не -1 с errno. snprintf возвращает длину, которая получилась бы без обрезания: сравните её с size и с 15. Чтение каталога - opendir/readdir, файл comm - fopen/fgets, перевод строки убирайте через strcspn.', '{"driver": "/*__DRIVER__*/\nstatic pthread_barrier_t bar;\n\nstatic void *vcpu_main(void *arg) {\n    char name[32];\n    int idx = (int)(long)arg;\n    if (vcpu_thread_name(name, sizeof name, idx) == 0)\n        thread_set_name(name);\n    pthread_barrier_wait(&bar);\n    pthread_barrier_wait(&bar);\n    return NULL;\n}\n\nstatic void *long_main(void *arg) {\n    *(int *)arg = thread_set_name(\"IO a-very-long-iothread-id\");\n    return NULL;\n}\n\nstatic int cmp(const void *a, const void *b) { return strcmp((const char *)a, (const char *)b); }\n\nint main(void) {\n    pthread_t t[3];\n    pthread_barrier_init(&bar, NULL, 4);\n    for (long i = 0; i < 3; i++)\n        pthread_create(&t[i], NULL, vcpu_main, (void *)i);\n    pthread_barrier_wait(&bar);\n    char names[16][16];\n    int n = other_thread_names(names, 16);\n    qsort(names, n > 0 ? n : 0, 16, cmp);\n    printf(\"%d\\n\", n);\n    for (int i = 0; i < n; i++)\n        printf(\"%s\\n\", names[i]);\n    pthread_barrier_wait(&bar);\n    for (int i = 0; i < 3; i++)\n        pthread_join(t[i], NULL);\n\n    int rc = -1;\n    pthread_t lt;\n    pthread_create(&lt, NULL, long_main, &rc);\n    pthread_join(lt, NULL);\n    printf(\"long name: %s\\n\", rc == ERANGE ? \"ERANGE\" : \"other\");\n\n    char buf[32];\n    printf(\"15 chars: %d ''%s''\\n\", vcpu_thread_name(buf, sizeof buf, 1234567), buf);\n    printf(\"16 chars: %d ''%s''\\n\", vcpu_thread_name(buf, sizeof buf, 12345678), buf);\n    printf(\"small buffer: %d ''%s''\\n\", vcpu_thread_name(buf, 8, 1), buf);\n    return 0;\n}\n", "expected": ["3", "CPU 0/KVM", "CPU 1/KVM", "CPU 2/KVM", "long name: ERANGE", "15 chars: 0 ''CPU 1234567/KVM''", "16 chars: -1 ''''", "small buffer: -1 ''''"], "flags": "-std=gnu11 -O1 -Wall"}');
